function sectionFromLibrary(item:LibraryItem):BuilderSection{
  const title=item.type==='navbar'?'BLOCKCTRL':item.type==='hero'?'Sınırsız Macera Seni Bekliyor':item.type==='footer'?'Daha fazlası senin elinde':item.type==='cta'?'Macera şimdi başlıyor':item.type==='contact'?'Bizimle iletişime geç':item.type==='pricing'?'Sana uygun paketi seç':item.type==='faq'?'Sıkça Sorulan Sorular':item.type==='team'?'Ekibimiz':item.type==='gallery'?'Dünyamızı keşfet':item.type==='map'?'Dünya Haritası':item.type==='testimonials'?'Topluluğumuz ne diyor?':item.type==='stats'?'Rakamlarla biz':item.type==='minecraft'?'Sunucu Bilgileri':item.type==='support'?'Destek Merkezi':item.type==='banlist'?'Banlı Oyuncular':item.type==='leaderboard'?'Oyuncu Sıralaması':item.type==='wiki'?'Sunucu Wiki':item.type==='guide'?'Oyuncu Rehberi':item.type==='connect'?'Sunucuya Nasıl Bağlanırsınız?':item.type==='store'?'Sunucu Mağazası':item.type==='login'?'Tekrar Hoş Geldin':item.type==='register'?'Topluluğa Katıl':item.type==='member-dashboard'?'Hesabım':'Öne Çıkan Özellikler'
  const body=item.type==='banlist'?'Aktif cezaları, sebepleri ve süreleri düzenleyin; itiraz bağlantısını ekleyin.':item.type==='leaderboard'?'Kill, ölüm, para, can/seviye ve oynama süresi gibi sıralama örneklerini düzenleyin.':item.type==='wiki'?'Sunucunun sistemlerini ve oyuncuların ihtiyaç duyacağı bilgileri kategoriler halinde yayınlayın.':item.type==='guide'?'Yeni ve deneyimli oyuncular için adım adım rehberler hazırlayın.':item.type==='connect'?'Java ve Bedrock oyuncularına sunucuya katılma adımlarını açıkça gösterin.':item.type==='map'?'BlueMap veya Dynmap haritanızı gömün; spawn, market ve önemli bölgeleri oyuncularınıza gösterin.':item.type==='store'?'Rütbe, kozmetik, kasa anahtarı ve coin ürünlerini istediğiniz gibi düzenleyin.':item.type==='login'?'E-posta ve şifrenizle giriş yapın.':item.type==='register'?'Website hesabınızı oluşturun ve oyuncu profilinizi bağlayın.':item.type==='member-dashboard'?'Profilinizi, üyelik bilgilerinizi ve bağlı sunucu canlı verilerini görüntüleyin.':item.type==='support'?'Oyuncuların destek, ödeme, hata bildirimi ve ban itirazı yollarını tek sayfada gösterin.':'İçeriği seçin, düzenleyin ve kendi tasarımınıza göre özelleştirin.'
  return {id:uid(),type:item.type,variant:item.variant,label:`${item.category} · ${item.label}`,title,subtitle:item.description,body,buttonText:item.type==='navbar'?'Şimdi Katıl':item.type==='support'?'Destek Talebi Aç':item.type==='banlist'?'Ban İtirazı Yap':item.type==='connect'?'IP Adresini Kopyala':item.type==='map'?'Haritayı Aç':item.type==='store'?'Mağazayı Gör':item.type==='login'?'Giriş Yap':item.type==='register'?'Kayıt Ol':item.type==='member-dashboard'?'Çıkış Yap':'Hemen Başla',buttonHref:'#',secondaryButtonText:'Daha Fazla Bilgi',secondaryButtonHref:'#',items:defaultItems(item.type,item.variant),liveData:defaultLiveData(item.type,item.variant),background:defaultBackground(),settings:{width:'wide',align:item.type==='hero'?'left':'center',paddingY:item.type==='navbar'?18:64,minHeight:item.type==='hero'?520:item.type==='navbar'?72:220,placement:'flow',visible:true,rounded:0}}
}
function findLibrary(type:string,index=0){return LIBRARY.filter(item=>item.type===type)[index]??LIBRARY[0]}
function templateSections(template:string):BuilderSection[]{
  const add=(type:string,index=0)=>sectionFromLibrary(findLibrary(type,index))
  if(template==='blank')return []
  if(template==='minecraft')return [add('navbar',0),add('hero',6),add('minecraft',0),add('features',4),add('stats',3),add('map',0),add('cta',0),add('footer',0)]
  if(template==='community')return [add('navbar',1),add('hero',4),add('minecraft',3),add('testimonials',1),add('team',1),add('contact',0),add('footer',3)]
  if(template==='support-page')return [add('navbar',0),add('hero',3),add('support',0),add('faq',0),add('contact',0),add('cta',1),add('footer',0)]
  if(template==='banned-page')return [add('navbar',1),add('hero',3),add('banlist',0),add('support',2),add('faq',0),add('footer',1)]
  if(template==='ranking-page')return [add('navbar',0),add('hero',4),add('leaderboard',0),add('leaderboard',1),add('leaderboard',2),add('leaderboard',3),add('leaderboard',4),add('stats',3),add('footer',2)]
  if(template==='wiki-page')return [add('navbar',3),add('hero',3),add('wiki',0),add('wiki',1),add('faq',1),add('footer',1)]
  if(template==='guide-page')return [add('navbar',3),add('hero',3),add('guide',0),add('guide',1),add('connect',0),add('faq',0),add('footer',1)]
  if(template==='connect-page')return [add('navbar',0),add('hero',2),add('connect',0),add('guide',0),add('faq',0),add('support',3),add('footer',0)]
  if(template==='map-page')return [add('navbar',0),add('hero',3),add('map',0),add('guide',1),add('cta',1),add('footer',0)]
  if(template==='store-page')return [add('navbar',0),add('hero',1),add('store',4),add('store',0),add('store',1),add('faq',0),add('cta',2),add('footer',4)]
  if(template==='login-page')return [add('navbar',3),add('login',0),add('footer',1)]
  if(template==='register-page')return [add('navbar',3),add('register',0),add('footer',1)]
  if(template==='member-dashboard-page')return [add('navbar',3),add('member-dashboard',0),add('stats',3),add('minecraft',0),add('footer',1)]
  if(template==='corporate')return [add('navbar',3),add('hero',7),add('features',2),add('stats',2),add('content',0),add('team',0),add('contact',2),add('footer',0)]
  if(template==='portfolio')return [add('navbar',4),add('hero',3),add('gallery',1),add('content',1),add('testimonials',3),add('contact',3),add('footer',2)]
  if(template==='shop')return [add('navbar',0),add('hero',1),add('features',4),add('pricing',1),add('gallery',0),add('cta',2),add('footer',4)]
  if(template==='landing')return [add('navbar',4),add('hero',0),add('features',0),add('stats',0),add('testimonials',0),add('faq',0),add('cta',0),add('footer',1)]
  return [add('navbar',3),add('hero',3),add('content',2),add('footer',1)]
}
export function defaultBuilderData(siteName:string,template='minecraft',serverId=''):WebsiteBuilderData{
  return {version:1,theme:{primary:'#0ea5e9',secondary:'#7c3aed',background:'#030b13',text:'#f4f9ff',muted:'#91a9bb',fontFamily:'Inter, ui-sans-serif, system-ui, sans-serif',radius:18},binding:{serverId,inheritLiveData:true},auth:{enabled:false,allowRegistration:true,registrationMode:'website',loginMode:'email',serverId:'',sessionDays:30,defaultRole:'member',loginPageSlug:'giris',registerPageSlug:'kayit',afterLoginPageSlug:'hesabim'},pages:[{id:uid(),name:'Ana Sayfa',slug:'',seoTitle:siteName,seoDescription:'BlockCtrl ile oluşturulan website.',showInNav:true,pageType:'standard',requiresAuth:false,accessMode:'public',allowedRoles:[],sections:templateSections(template)}]}
}
function cloneBuilder(data:WebsiteBuilderData){return JSON.parse(JSON.stringify(data)) as WebsiteBuilderData}
function pageHref(page:BuilderPage){return page.slug?`/${page.slug}`:'/'}

export function WebsiteBuilder({open,site,onClose,onSaved}:{open:boolean;site:BuilderWebsite|null;onClose:()=>void;onSaved:(site?:BuilderWebsite)=>Promise<void>|void}){
  const[draft,setDraft]=useState<WebsiteBuilderData>(()=>defaultBuilderData(site?.name??'Website',site?.template??'minecraft'))
  const[activePageId,setActivePageId]=useState('')
  const[selectedSectionId,setSelectedSectionId]=useState<string|null>(null)
  const[leftTab,setLeftTab]=useState<'sections'|'pages'|'templates'>('sections')
  const[device,setDevice]=useState<'desktop'|'tablet'|'mobile'>('desktop')
  const[preview,setPreview]=useState(false)
  const[busy,setBusy]=useState(false)
  const[message,setMessage]=useState('')
  const[dirty,setDirty]=useState(false)
  const[dragSection,setDragSection]=useState<string|null>(null)
  const[dragLibrary,setDragLibrary]=useState<string|null>(null)
  const[expandedCategory,setExpandedCategory]=useState<string>('Navigasyon')
  const[newPageTemplate,setNewPageTemplate]=useState('blank')
  const[uploading,setUploading]=useState(false)
  const[dataSources,setDataSources]=useState<{servers:LiveServerOption[];sourceTypes:LiveSourceType[]}>({servers:[],sourceTypes:[]})

  useEffect(()=>{
    if(!open||!site)return
    const raw=site.builderData&&Array.isArray(site.builderData.pages)&&site.builderData.pages.length?cloneBuilder(site.builderData):defaultBuilderData(site.name,site.template)
    const authDefaults:WebsiteAuthSettings={enabled:false,allowRegistration:true,registrationMode:'website',loginMode:'email',serverId:'',sessionDays:30,defaultRole:'member',loginPageSlug:'giris',registerPageSlug:'kayit',afterLoginPageSlug:'hesabim'}
    const bindingDefaults={serverId:site.serverId||'',inheritLiveData:true}
    const rawBinding=((raw as any).binding||{}) as Partial<WebsiteBuilderData['binding']>;const next:WebsiteBuilderData={...raw,binding:{...bindingDefaults,...rawBinding,serverId:site.serverId||rawBinding.serverId||''},auth:{...authDefaults,...(raw.auth||{})},pages:raw.pages.map((page,index)=>({...page,pageType:page.pageType||'standard',requiresAuth:Boolean(page.requiresAuth),accessMode:page.accessMode||(page.requiresAuth?'authenticated':'public'),allowedRoles:Array.isArray(page.allowedRoles)?page.allowedRoles:[],sections:page.sections.map(section=>({...section,liveData:section.liveData||defaultLiveData(section.type,section.variant)}))}))}
    setDraft(next);setActivePageId(next.pages[0]?.id??'');setSelectedSectionId(next.pages[0]?.sections[0]?.id??null);setDirty(false);setMessage('');setPreview(false)
  },[open,site?.id])
  useEffect(()=>{if(!open||!site)return;let cancelled=false;const load=async()=>{try{const response=await fetch(`/api/website-data-sources?websiteId=${encodeURIComponent(site.id)}`,{cache:'no-store'});const payload=await response.json();if(!cancelled&&response.ok)setDataSources({servers:Array.isArray(payload.servers)?payload.servers:[],sourceTypes:Array.isArray(payload.sourceTypes)?payload.sourceTypes:[]})}catch{}};void load();const timer=window.setInterval(load,10000);return()=>{cancelled=true;window.clearInterval(timer)}},[open,site?.id])

  const activePage=useMemo(()=>draft.pages.find(page=>page.id===activePageId)??draft.pages[0],[draft.pages,activePageId])
  const selected=useMemo(()=>activePage?.sections.find(section=>section.id===selectedSectionId)??null,[activePage,selectedSectionId])
  const canvasWidth=device==='desktop'?'100%':device==='tablet'?'820px':'390px'
  function change(next:WebsiteBuilderData){setDraft(next);setDirty(true)}
  function patchTheme(patch:Partial<WebsiteBuilderData['theme']>){change({...draft,theme:{...draft.theme,...patch}})}
  function patchPage(patch:Partial<BuilderPage>){if(!activePage)return;change({...draft,pages:draft.pages.map(p=>p.id===activePage.id?{...p,...patch}:p)})}
  function patchSection(id:string,patch:Partial<BuilderSection>){if(!activePage)return;change({...draft,pages:draft.pages.map(p=>p.id===activePage.id?{...p,sections:p.sections.map(s=>s.id===id?{...s,...patch}:s)}:p)})}
  function patchSelected(patch:Partial<BuilderSection>){if(selected)patchSection(selected.id,patch)}
  function patchSettings(patch:Partial<BuilderSection['settings']>){if(selected)patchSection(selected.id,{settings:{...selected.settings,...patch}})}
  function patchBackground(patch:Partial<BuilderBackground>){if(selected)patchSection(selected.id,{background:{...selected.background,...patch}})}
  function patchLiveData(patch:Partial<BuilderLiveData>){if(selected)patchSection(selected.id,{liveData:{...selected.liveData,...patch}})}
  function patchAuth(patch:Partial<WebsiteAuthSettings>){change({...draft,auth:{...draft.auth,...patch}})}
  function setPrimaryServer(serverId:string){
    const previous=draft.binding.serverId
    const pages=draft.pages.map(page=>({...page,sections:page.sections.map(section=>{
      if(section.liveData.mode==='static'||section.liveData.source==='custom-json')return section
      if(!section.liveData.serverId||section.liveData.serverId===previous)return {...section,liveData:{...section.liveData,serverId:''}}
      return section
    })}))
    const authServerId=(!draft.auth.serverId||draft.auth.serverId===previous)?'':draft.auth.serverId
    change({...draft,binding:{...draft.binding,serverId},auth:{...draft.auth,serverId:authServerId},pages})
    setMessage(serverId?'Ana sunucu değiştirildi. Otomatik bağlı bölümler bağlantıyı devralmaya devam edecek.':'Ana sunucu bağlantısı kaldırıldı.')
  }
  function addSection(item:LibraryItem,index?:number){if(!activePage)return;const block=sectionFromLibrary(item);const sections=[...activePage.sections];if(typeof index==='number')sections.splice(index,0,block);else sections.push(block);change({...draft,pages:draft.pages.map(p=>p.id===activePage.id?{...p,sections}:p)});setSelectedSectionId(block.id)}
  function removeSection(id:string){if(!activePage)return;const sections=activePage.sections.filter(s=>s.id!==id);change({...draft,pages:draft.pages.map(p=>p.id===activePage.id?{...p,sections}:p)});if(selectedSectionId===id)setSelectedSectionId(sections[0]?.id??null)}
  function duplicateSection(id:string){if(!activePage)return;const index=activePage.sections.findIndex(s=>s.id===id);if(index<0)return;const copy={...cloneBuilder({version:1,theme:draft.theme,binding:draft.binding,auth:draft.auth,pages:[{...activePage,sections:[activePage.sections[index]]}]}).pages[0].sections[0],id:uid(),label:`${activePage.sections[index].label} kopya`};const sections=[...activePage.sections];sections.splice(index+1,0,copy);change({...draft,pages:draft.pages.map(p=>p.id===activePage.id?{...p,sections}:p)});setSelectedSectionId(copy.id)}
  function moveSection(id:string,direction:-1|1){if(!activePage)return;const sections=[...activePage.sections];const index=sections.findIndex(s=>s.id===id),target=index+direction;if(index<0||target<0||target>=sections.length)return;[sections[index],sections[target]]=[sections[target],sections[index]];change({...draft,pages:draft.pages.map(p=>p.id===activePage.id?{...p,sections}:p)})}
  function dropOn(targetId?:string){if(!activePage)return;const targetIndex=targetId?activePage.sections.findIndex(s=>s.id===targetId):activePage.sections.length
    if(dragLibrary){const item=LIBRARY.find(x=>x.id===dragLibrary);if(item)addSection(item,targetIndex<0?undefined:targetIndex);setDragLibrary(null);return}
    if(dragSection){const sections=[...activePage.sections];const from=sections.findIndex(s=>s.id===dragSection);let to=targetIndex;if(from<0)return;const[item]=sections.splice(from,1);if(from<to)to--;sections.splice(Math.max(0,Math.min(to,sections.length)),0,item);change({...draft,pages:draft.pages.map(p=>p.id===activePage.id?{...p,sections}:p)});setDragSection(null)}
  }
  function addPage(){const name=`Yeni Sayfa ${draft.pages.length+1}`;const page:BuilderPage={id:uid(),name,slug:slugify(name),seoTitle:name,seoDescription:'',showInNav:true,pageType:newPageTemplate==='login-page'?'login':newPageTemplate==='register-page'?'register':newPageTemplate==='member-dashboard-page'?'member-dashboard':'standard',requiresAuth:newPageTemplate==='member-dashboard-page',accessMode:newPageTemplate==='member-dashboard-page'?'authenticated':'public',allowedRoles:[],sections:templateSections(newPageTemplate).map(section=>section.liveData.mode!=='static'&&section.liveData.source!=='custom-json'?{...section,liveData:{...section.liveData,serverId:''}}:section)};change({...draft,pages:[...draft.pages,page]});setActivePageId(page.id);setSelectedSectionId(page.sections[0]?.id??null);setLeftTab('sections')}
  function addCommunityPagePack(){
    const used=new Set(draft.pages.map(page=>page.slug))
    const additions=COMMUNITY_PAGE_PACK.filter(item=>!used.has(item.slug)).map(item=>({id:uid(),name:item.name,slug:item.slug,seoTitle:item.seo,seoDescription:`${item.name} sayfası`,showInNav:true,pageType:'standard',requiresAuth:false,accessMode:'public',allowedRoles:[],sections:templateSections(item.template).map(section=>section.liveData.mode!=='static'&&section.liveData.source!=='custom-json'?{...section,liveData:{...section.liveData,serverId:''}}:section)} as BuilderPage))
    if(!additions.length){setMessage('Hazır Minecraft website sayfalarının tamamı zaten ekli.');return}
    if(draft.pages.length+additions.length>20){setMessage('Website en fazla 20 sayfa içerebilir.');return}
    change({...draft,pages:[...draft.pages,...additions]});setActivePageId(additions[0].id);setSelectedSectionId(additions[0].sections[0]?.id??null);setMessage(`${additions.length} hazır sayfa eklendi. Her bölüm düzenlenebilir, taşınabilir ve silinebilir.`)
  }
  function addMemberPagePack(){
    const used=new Set(draft.pages.map(page=>page.slug))
    const additions=MEMBER_PAGE_PACK.filter(item=>!used.has(item.slug)).map(item=>({id:uid(),name:item.name,slug:item.slug,seoTitle:item.seo,seoDescription:`${item.name} sayfası`,showInNav:item.pageType==='member-dashboard',pageType:item.pageType,requiresAuth:item.requiresAuth,accessMode:item.requiresAuth?'authenticated':'public',allowedRoles:[],sections:templateSections(item.template).map(section=>section.liveData.mode!=='static'&&section.liveData.source!=='custom-json'?{...section,liveData:{...section.liveData,serverId:''}}:section)} as BuilderPage))
    if(!additions.length){setMessage('Giriş, kayıt ve üye paneli sayfaları zaten ekli.');return}
    if(draft.pages.length+additions.length>20){setMessage('Website en fazla 20 sayfa içerebilir.');return}
    change({...draft,auth:{...draft.auth,enabled:true,registrationMode:draft.auth.registrationMode||'website',loginMode:draft.auth.loginMode||'email',loginPageSlug:'giris',registerPageSlug:'kayit',afterLoginPageSlug:'hesabim'},pages:[...draft.pages,...additions]});setActivePageId(additions[0].id);setSelectedSectionId(additions[0].sections[0]?.id??null);setMessage('Üye sistemi sayfaları eklendi ve üye sistemi etkinleştirildi.')
  }
  function duplicatePage(page:BuilderPage){const copy=cloneBuilder({version:1,theme:draft.theme,binding:draft.binding,auth:draft.auth,pages:[page]}).pages[0];copy.id=uid();copy.name=`${page.name} Kopya`;copy.slug=`${page.slug||'sayfa'}-kopya-${draft.pages.length}`;copy.sections=copy.sections.map(section=>({...section,id:uid()}));change({...draft,pages:[...draft.pages,copy]});setActivePageId(copy.id)}
  function deletePage(page:BuilderPage){if(draft.pages.length<=1){setMessage('Website içinde en az bir sayfa bulunmalıdır.');return}if(!window.confirm(`“${page.name}” sayfası silinsin mi?`))return;const pages=draft.pages.filter(p=>p.id!==page.id);change({...draft,pages});if(activePageId===page.id){setActivePageId(pages[0].id);setSelectedSectionId(pages[0].sections[0]?.id??null)}}
  async function save(publish=false){if(!site)return;setBusy(true);setMessage('');try{const response=await fetch('/api/websites',{method:'POST',headers:{'content-type':'application/json'},body:JSON.stringify({action:publish?'publish':'save-builder',websiteId:site.id,builderData:draft})});const text=await response.text();const payload=text?JSON.parse(text):{};if(!response.ok)throw new Error(String(payload.error??`İşlem başarısız (${response.status})`));setDirty(false);setMessage(publish?'Website başarıyla yayın kuyruğuna alındı.':'Taslak kaydedildi.');await onSaved(payload.website)}catch(e){setMessage(e instanceof Error?e.message:'İşlem başarısız.')}finally{setBusy(false)}}
  async function uploadBackground(file:File){if(!site||!selected)return;setUploading(true);setMessage('');try{if(!file.type.startsWith('image/')&&!file.type.startsWith('video/'))throw new Error('Yalnız görsel veya video yükleyebilirsiniz.');const pathname=`websites/${site.id}/${uid()}-${file.name.replace(/[^a-zA-Z0-9._-]/g,'_').slice(-120)}`;const modeResponse=await fetch(`/api/website-upload?websiteId=${encodeURIComponent(site.id)}`,{cache:'no-store'});const modeText=await modeResponse.text();const mode=modeText?JSON.parse(modeText) as {mode?:'blob'|'database';maxBytes?:number;error?:string}:{};if(!modeResponse.ok)throw new Error(String(mode.error||'Medya depolama durumu alınamadı.'));let mediaUrl='';if(mode.mode==='blob'){const blob=await upload(pathname,file,{access:'public',handleUploadUrl:'/api/website-upload',clientPayload:JSON.stringify({websiteId:site.id}),multipart:true});mediaUrl=blob.url}else{if(file.size>Number(mode.maxBytes||0))throw new Error(`Blob bağlı değilken dosya sınırı ${Math.round(Number(mode.maxBytes||0)/1048576)} MB.`);const form=new FormData();form.set('websiteId',site.id);form.set('pathname',pathname);form.set('file',file);const response=await fetch('/api/website-upload',{method:'POST',body:form});const text=await response.text();const payload=text?JSON.parse(text) as {url?:string;error?:string}:{};if(!response.ok||!payload.url)throw new Error(String(payload.error||'Medya yüklenemedi.'));mediaUrl=payload.url}patchBackground({type:file.type.startsWith('video/')?'video':'image',mediaUrl})}catch(e){setMessage(e instanceof Error?e.message:'Medya yüklenemedi.')}finally{setUploading(false)}}

  if(!site)return null
  return <Dialog open={open} onOpenChange={value=>{if(!value){if(dirty&&!window.confirm('Kaydedilmemiş değişiklikler var. Çıkılsın mı?'))return;onClose()}}}>
    <DialogContent className="h-[96svh] w-[98vw] max-w-[1880px] overflow-hidden border-sky-400/20 bg-[#030b13] p-0 text-slate-100 sm:max-w-[1880px]">
      <div className="flex h-full min-h-0 flex-col">
        <DialogHeader className="sr-only"><DialogTitle>Website Tasarım Editörü</DialogTitle><DialogDescription>Sürükle bırak website oluşturucu.</DialogDescription></DialogHeader>
        <div className="flex min-h-16 flex-wrap items-center gap-3 border-b border-sky-400/15 bg-[#061421]/95 px-4 py-3">
          <div className="min-w-0"><p className="text-xs text-cyan-300">Websiteler / {site.name}</p><h2 className="truncate text-lg font-bold text-white">Website Tasarım Editörü</h2></div>
          <div className="ml-auto flex flex-wrap items-center gap-2">
            <label className="hidden items-center gap-2 rounded-xl border border-cyan-400/15 bg-[#071827] px-2 py-1.5 text-xs text-slate-400 lg:flex"><DatabaseZap className="size-3.5 text-cyan-300"/><span>Ana sunucu</span><select className="h-8 max-w-56 rounded-lg border border-white/10 bg-[#061421] px-2 text-xs text-white" value={draft.binding.serverId} onChange={e=>setPrimaryServer(e.target.value)}><option value="">Bağlantı yok</option>{dataSources.servers.map(server=><option key={server.id} value={server.id}>{server.name} · {server.status}{server.map?.configured?' · Harita hazır':''}</option>)}</select></label>
            <div className="hidden items-center rounded-xl border border-sky-400/15 bg-[#071827] p-1 sm:flex"><Button size="icon" variant={device==='desktop'?'secondary':'ghost'} onClick={()=>setDevice('desktop')} title="Masaüstü"><Monitor className="size-4"/></Button><Button size="icon" variant={device==='tablet'?'secondary':'ghost'} onClick={()=>setDevice('tablet')} title="Tablet"><Tablet className="size-4"/></Button><Button size="icon" variant={device==='mobile'?'secondary':'ghost'} onClick={()=>setDevice('mobile')} title="Mobil"><Smartphone className="size-4"/></Button></div>
            <Button variant="outline" className="border-sky-400/25" onClick={()=>setPreview(v=>!v)}><Eye className="size-4"/>{preview?'Editöre Dön':'Önizle'}</Button>
            {!preview&&<Button variant="outline" className="border-sky-400/25" disabled={busy||!dirty} onClick={()=>void save(false)}>{busy?<LoaderCircle className="size-4 animate-spin"/>:<Save className="size-4"/>}Kaydet</Button>}
            <Button className="bg-gradient-to-r from-cyan-500 to-blue-600 text-white" disabled={busy} onClick={()=>void save(true)}>{busy?<LoaderCircle className="size-4 animate-spin"/>:<Rocket className="size-4"/>}Yayınla</Button>
            <Button size="icon" variant="ghost" onClick={onClose} aria-label="Kapat"><X className="size-5"/></Button>
          </div>
        </div>
        {message&&<div className={`border-b px-4 py-2 text-sm ${message.includes('başarı')||message.includes('kaydedildi')?'border-emerald-500/20 bg-emerald-500/10 text-emerald-200':'border-amber-500/20 bg-amber-500/10 text-amber-100'}`}>{message}</div>}
        <div className={`grid min-h-0 flex-1 ${preview?'grid-cols-1':'xl:grid-cols-[330px_minmax(0,1fr)_340px]'}`}>
          {!preview&&<aside className="min-h-0 overflow-y-auto border-r border-sky-400/15 bg-[#061421]/90 p-3">
            <div className="grid grid-cols-3 rounded-xl border border-sky-400/15 bg-[#071827] p-1 text-xs"><button className={`rounded-lg px-2 py-2 ${leftTab==='sections'?'bg-sky-500/15 text-cyan-200':'text-slate-400'}`} onClick={()=>setLeftTab('sections')}>Bölümler</button><button className={`rounded-lg px-2 py-2 ${leftTab==='pages'?'bg-sky-500/15 text-cyan-200':'text-slate-400'}`} onClick={()=>setLeftTab('pages')}>Sayfalar</button><button className={`rounded-lg px-2 py-2 ${leftTab==='templates'?'bg-sky-500/15 text-cyan-200':'text-slate-400'}`} onClick={()=>setLeftTab('templates')}>Hazır</button></div>
            {leftTab==='sections'&&<div className="mt-3 space-y-2"><div className="rounded-xl border border-cyan-400/15 bg-cyan-400/[.04] p-3"><p className="text-xs font-semibold text-cyan-300">Sürükle ve bırak</p><p className="mt-1 text-xs leading-5 text-slate-500">Bir tasarımı tuvale sürükleyin veya tıklayarak sayfanın sonuna ekleyin. Tüm bölümler sonradan değiştirilebilir.</p></div>{CATEGORY_ORDER.map(category=>{const items=LIBRARY.filter(item=>item.category===category);const expanded=expandedCategory===category;return <div key={category} className="overflow-hidden rounded-xl border border-white/10 bg-white/[.02]"><button className="flex w-full items-center justify-between gap-2 px-3 py-2.5 text-left text-sm font-medium" onClick={()=>setExpandedCategory(expanded?'':category)}><span>{category} <span className="text-xs text-slate-500">({items.length})</span></span>{expanded?<ChevronDown className="size-4"/>:<ChevronRight className="size-4"/>}</button>{expanded&&<div className="grid grid-cols-2 gap-2 border-t border-white/5 p-2">{items.map(item=><button key={item.id} draggable onDragStart={()=>setDragLibrary(item.id)} onClick={()=>addSection(item)} className="group rounded-lg border border-white/10 bg-[#081a2a] p-2 text-left transition hover:border-cyan-400/40 hover:bg-cyan-400/[.06]"><div className="aspect-[16/9] rounded-md border border-white/5 bg-[linear-gradient(145deg,#0b2c48,#07121e)] p-2"><div className="h-2 w-12 rounded bg-cyan-400/50"/><div className="mt-2 h-1.5 w-3/4 rounded bg-white/15"/><div className="mt-1 h-1.5 w-1/2 rounded bg-white/10"/></div><p className="mt-2 text-xs font-medium text-slate-200">{item.label}</p></button>)}</div>}</div>})}</div>}
            {leftTab==='pages'&&<div className="mt-3 space-y-3"><div className="rounded-xl border border-sky-400/15 bg-[#071827] p-3"><p className="text-sm font-semibold">Yeni sayfa ekle</p><select className="mt-2 h-10 w-full rounded-lg border border-white/10 bg-[#061421] px-3 text-sm" value={newPageTemplate} onChange={e=>setNewPageTemplate(e.target.value)}>{PAGE_TEMPLATES.map(item=><option key={item.id} value={item.id}>{item.name}</option>)}</select><Button className="mt-2 w-full" variant="outline" onClick={addPage}><FilePlus2 className="size-4"/>Sayfa Ekle</Button><Button className="mt-2 w-full border-cyan-400/30 bg-cyan-400/[.06] text-cyan-100" variant="outline" onClick={addCommunityPagePack}><Layers3 className="size-4"/>7 Hazır Minecraft Sayfasını Ekle</Button><Button className="mt-2 w-full border-violet-400/30 bg-violet-400/[.06] text-violet-100" variant="outline" onClick={addMemberPagePack}><UserPlus className="size-4"/>Giriş + Kayıt + Üye Panelini Ekle</Button><p className="mt-2 text-[11px] leading-5 text-slate-500">Hazır sayfalar eklendikten sonra tüm bölümleri düzenleyebilir veya silebilirsiniz.</p></div><div className="rounded-xl border border-violet-400/15 bg-violet-400/[.04] p-3"><div className="flex items-center justify-between gap-2"><div><p className="text-sm font-semibold text-violet-100">Website Üye Sistemi</p><p className="mt-1 text-xs text-slate-500">E-posta, Minecraft hesabı veya sunucu üzerinden kayıt akışını seçin.</p></div><input type="checkbox" checked={draft.auth.enabled} onChange={e=>patchAuth({enabled:e.target.checked})} className="accent-violet-400"/></div>{draft.auth.enabled&&<div className="mt-3 space-y-2"><label className="text-xs text-slate-400">Kayıt yöntemi<select className="mt-1 h-10 w-full rounded-lg border border-white/10 bg-[#071827] px-2 text-sm" value={draft.auth.registrationMode} onChange={e=>{const registrationMode=e.target.value as WebsiteAuthSettings['registrationMode'];patchAuth({registrationMode,allowRegistration:registrationMode==='website'||registrationMode==='both'})}}><option value="website">Website üzerinden kayıt</option><option value="server">Yalnız sunucu üzerinden kayıt</option><option value="both">Website + sunucu</option><option value="closed">Kayıt kapalı / yalnız yönetici</option></select></label><label className="text-xs text-slate-400">Giriş kimliği<select className="mt-1 h-10 w-full rounded-lg border border-white/10 bg-[#071827] px-2 text-sm" value={draft.auth.loginMode} onChange={e=>patchAuth({loginMode:e.target.value as WebsiteAuthSettings['loginMode']})}><option value="email">E-posta + şifre</option><option value="minecraft">Minecraft kullanıcı adı + şifre</option><option value="both">E-posta veya Minecraft kullanıcı adı</option></select></label>{(draft.auth.registrationMode==='server'||draft.auth.registrationMode==='both')&&<label className="text-xs text-slate-400">Bağlı Minecraft sunucusu<select className="mt-1 h-10 w-full rounded-lg border border-white/10 bg-[#071827] px-2 text-sm" value={draft.auth.serverId} onChange={e=>patchAuth({serverId:e.target.value})}><option value="">Otomatik · website ana sunucusu</option>{dataSources.servers.map(server=><option key={server.id} value={server.id}>{server.name} · {server.status}</option>)}</select></label>}<label className="text-xs text-slate-400">Oturum süresi<select className="mt-1 h-10 w-full rounded-lg border border-white/10 bg-[#071827] px-2 text-sm" value={draft.auth.sessionDays} onChange={e=>patchAuth({sessionDays:Number(e.target.value)})}><option value={1}>1 gün</option><option value={7}>7 gün</option><option value={30}>30 gün</option><option value={90}>90 gün</option></select></label><LabelInput label="Varsayılan üye rolü" value={draft.auth.defaultRole} onChange={value=>patchAuth({defaultRole:slugify(value)||'member'})}/><LabelInput label="Giriş sayfası URL" value={draft.auth.loginPageSlug} onChange={value=>patchAuth({loginPageSlug:slugify(value)})}/><LabelInput label="Kayıt sayfası URL" value={draft.auth.registerPageSlug} onChange={value=>patchAuth({registerPageSlug:slugify(value)})}/><LabelInput label="Giriş sonrası URL" value={draft.auth.afterLoginPageSlug} onChange={value=>patchAuth({afterLoginPageSlug:slugify(value)})}/><div className="rounded-lg border border-cyan-400/15 bg-cyan-400/[.04] p-2 text-[11px] leading-5 text-slate-400"><LockKeyhole className="mr-1 inline size-3.5 text-cyan-300"/>Sunucu kayıt modu, BlockCtrl server bridge üzerinden oluşturulan/bağlanan Minecraft üyelerini kabul eder. Sunucu alanı Otomatik bırakılırsa website ana sunucusu devralınır; ana sunucu değiştiğinde bağlantı da güncellenir.</div></div>}</div>{draft.pages.map(page=><div key={page.id} className={`rounded-xl border p-3 ${activePage?.id===page.id?'border-cyan-400/45 bg-cyan-400/[.06]':'border-white/10 bg-white/[.02]'}`}><button className="w-full text-left" onClick={()=>{setActivePageId(page.id);setSelectedSectionId(page.sections[0]?.id??null)}}><p className="font-medium text-white">{page.name}</p><p className="mt-1 text-xs text-slate-500">{pageHref(page)} · {page.sections.length} bölüm</p></button><div className="mt-2 flex gap-1"><Button size="sm" variant="ghost" onClick={()=>duplicatePage(page)}><Copy className="size-3.5"/>Kopyala</Button><Button size="sm" variant="ghost" className="ml-auto text-red-300" onClick={()=>deletePage(page)}><Trash2 className="size-3.5"/></Button></div></div>)}</div>}
            {leftTab==='templates'&&<div className="mt-3 grid gap-3">{PAGE_TEMPLATES.filter(x=>x.id!=='blank').map(template=><button key={template.id} className="overflow-hidden rounded-xl border border-white/10 bg-white/[.02] text-left hover:border-cyan-400/40" onClick={()=>{if(!activePage)return;const sections=templateSections(template.id);if(activePage.sections.length&&!window.confirm('Mevcut sayfadaki bölümler bu hazır tasarımla değiştirilsin mi?'))return;patchPage({sections});setSelectedSectionId(sections[0]?.id??null)}}><div className="aspect-[16/7] bg-[linear-gradient(135deg,#0b2b45,#10203d,#24103c)] p-4"><div className="h-2 w-20 rounded bg-cyan-400/50"/><div className="mt-4 h-4 w-2/3 rounded bg-white/80"/><div className="mt-2 h-2 w-1/2 rounded bg-white/20"/></div><div className="p-3"><p className="font-medium">{template.name}</p><p className="mt-1 text-xs leading-5 text-slate-500">{template.description}</p></div></button>)}</div>}
          </aside>}

          <main className="min-h-0 overflow-auto bg-[radial-gradient(circle_at_top,#0a2036,transparent_40%),#02070d] p-3 md:p-5">
            {!activePage?<div className="grid h-full place-items-center text-slate-500">Sayfa bulunamadı.</div>:<div className="mx-auto transition-all" style={{width:canvasWidth,maxWidth:'100%'}}>
              {preview&&<div className="mb-3 flex flex-wrap items-center justify-center gap-2 rounded-xl border border-sky-400/15 bg-[#061421]/90 p-2"><span className="mr-1 text-xs text-slate-500">Website önizlemesi:</span>{draft.pages.map(page=><Button key={page.id} size="sm" variant={page.id===activePage.id?'secondary':'ghost'} onClick={()=>{setActivePageId(page.id);setSelectedSectionId(page.sections[0]?.id??null)}}>{page.name}</Button>)}</div>}
              {!preview&&<div className="mb-3 flex flex-wrap items-center gap-2 rounded-xl border border-sky-400/15 bg-[#061421]/90 p-2"><span className="text-xs text-slate-500">Sayfa:</span><select className="h-9 min-w-40 rounded-lg border border-white/10 bg-[#071827] px-3 text-sm" value={activePage.id} onChange={e=>{setActivePageId(e.target.value);const p=draft.pages.find(x=>x.id===e.target.value);setSelectedSectionId(p?.sections[0]?.id??null)}}>{draft.pages.map(p=><option key={p.id} value={p.id}>{p.name}</option>)}</select><Badge variant="outline" className="ml-auto border-cyan-400/20 text-cyan-200">{activePage.sections.length} bölüm</Badge></div>}
              <div className="relative overflow-hidden border border-sky-400/20 bg-[#030b13] shadow-[0_25px_80px_rgba(0,0,0,.4)]" style={{fontFamily:draft.theme.fontFamily,color:draft.theme.text,borderRadius:preview?0:draft.theme.radius}} onDragOver={e=>e.preventDefault()} onDrop={e=>{e.preventDefault();dropOn()}}>
                {activePage.sections.length?activePage.sections.map((section,index)=><div key={section.id} draggable={!preview} onDragStart={()=>setDragSection(section.id)} onDragOver={e=>e.preventDefault()} onDrop={e=>{e.stopPropagation();e.preventDefault();dropOn(section.id)}} className={`group relative ${!section.settings.visible?'opacity-40':''} ${!preview&&selectedSectionId===section.id?'outline outline-2 outline-cyan-400 outline-offset-[-2px]':''}`} onClick={()=>!preview&&setSelectedSectionId(section.id)}>
                  {!preview&&<div className="pointer-events-none absolute right-2 top-2 z-30 flex opacity-0 transition group-hover:pointer-events-auto group-hover:opacity-100"><div className="flex items-center rounded-lg border border-sky-400/20 bg-[#03101c]/95 p-1 shadow-xl"><span className="cursor-grab p-1 text-slate-400"><GripVertical className="size-4"/></span><Button size="icon" variant="ghost" className="size-8" disabled={index===0} onClick={e=>{e.stopPropagation();moveSection(section.id,-1)}}><ArrowUp className="size-4"/></Button><Button size="icon" variant="ghost" className="size-8" disabled={index===activePage.sections.length-1} onClick={e=>{e.stopPropagation();moveSection(section.id,1)}}><ArrowDown className="size-4"/></Button><Button size="icon" variant="ghost" className="size-8" onClick={e=>{e.stopPropagation();duplicateSection(section.id)}}><Copy className="size-4"/></Button><Button size="icon" variant="ghost" className="size-8 text-red-300" onClick={e=>{e.stopPropagation();removeSection(section.id)}}><Trash2 className="size-4"/></Button></div></div>}
                  <SectionPreview section={section} theme={draft.theme} pages={draft.pages} liveServer={section.liveData.mode==='static'?undefined:(dataSources.servers.find(server=>server.id===(section.liveData.serverId||draft.binding.serverId))||dataSources.servers[0])}/>
                </div>):!preview?<div className="grid min-h-[520px] place-items-center border-2 border-dashed border-cyan-400/15 p-10 text-center"><div><Layers3 className="mx-auto size-10 text-cyan-300/50"/><p className="mt-3 font-medium">Bu sayfa boş</p><p className="mt-1 text-sm text-slate-500">Soldan bir navbar, hero veya başka bir bölüm sürükleyin.</p></div></div>:null}
                {!preview&&<div className="m-3 grid min-h-20 place-items-center rounded-xl border border-dashed border-cyan-400/20 bg-cyan-400/[.03] text-xs text-slate-500" onDragOver={e=>e.preventDefault()} onDrop={e=>{e.preventDefault();dropOn()}}><Plus className="mr-1 inline size-4"/>Bölümü buraya bırak</div>}
              </div>
            </div>}
          </main>

          {!preview&&<aside className="min-h-0 overflow-y-auto border-l border-sky-400/15 bg-[#061421]/90 p-4">
            <div className="mb-4 flex items-center gap-2"><Settings2 className="size-4 text-cyan-300"/><h3 className="font-semibold">{selected?'Bölüm Ayarları':'Sayfa Ayarları'}</h3></div>
            {selected?<SectionSettings section={selected} patch={patchSelected} patchSettings={patchSettings} patchBackground={patchBackground} patchLiveData={patchLiveData} uploadBackground={uploadBackground} uploading={uploading} servers={dataSources.servers} sourceTypes={dataSources.sourceTypes} primaryServerId={draft.binding.serverId}/>:activePage?<PageSettings page={activePage} patch={patchPage}/>:null}
            <div className="mt-5 border-t border-white/10 pt-4"><p className="mb-3 text-xs font-semibold uppercase tracking-wider text-slate-500">Website Teması</p><div className="grid grid-cols-2 gap-3"><ColorField label="Ana renk" value={draft.theme.primary} onChange={value=>patchTheme({primary:value})}/><ColorField label="İkincil" value={draft.theme.secondary} onChange={value=>patchTheme({secondary:value})}/><ColorField label="Arka plan" value={draft.theme.background} onChange={value=>patchTheme({background:value})}/><ColorField label="Metin" value={draft.theme.text} onChange={value=>patchTheme({text:value})}/></div><label className="mt-3 block text-xs text-slate-400">Köşe yuvarlaklığı<input type="range" min="0" max="32" value={draft.theme.radius} onChange={e=>patchTheme({radius:Number(e.target.value)})} className="mt-2 w-full accent-cyan-400"/></label></div>
          </aside>}
        </div>
      </div>
    </DialogContent>
  </Dialog>
}

function SectionSettings({section,patch,patchSettings,patchBackground,patchLiveData,uploadBackground,uploading,servers,sourceTypes,primaryServerId}:{section:BuilderSection;patch:(p:Partial<BuilderSection>)=>void;patchSettings:(p:Partial<BuilderSection['settings']>)=>void;patchBackground:(p:Partial<BuilderBackground>)=>void;patchLiveData:(p:Partial<BuilderLiveData>)=>void;uploadBackground:(file:File)=>Promise<void>;uploading:boolean;servers:LiveServerOption[];sourceTypes:LiveSourceType[];primaryServerId:string}){
  return <div className="space-y-4"><div className="rounded-xl border border-cyan-400/15 bg-cyan-400/[.04] p-3"><p className="text-xs text-cyan-300">{section.label}</p><p className="mt-1 text-xs text-slate-500">Her bölüm taşınabilir, kopyalanabilir, gizlenebilir veya silinebilir.</p></div>
    <SettingsGroup title="İçerik"><LabelInput label="Başlık" value={section.title} onChange={value=>patch({title:value})}/><LabelInput label="Alt başlık" value={section.subtitle} onChange={value=>patch({subtitle:value})}/><label className="text-xs text-slate-400">Açıklama<textarea rows={4} className="mt-1 w-full rounded-lg border border-white/10 bg-[#071827] p-2.5 text-sm text-white" value={section.body} onChange={e=>patch({body:e.target.value})}/></label><div className="grid grid-cols-2 gap-2"><LabelInput label="Buton" value={section.buttonText} onChange={value=>patch({buttonText:value})}/><LabelInput label="Bağlantı" value={section.buttonHref} onChange={value=>patch({buttonHref:value})}/></div><div className="grid grid-cols-2 gap-2"><LabelInput label="2. Buton" value={section.secondaryButtonText} onChange={value=>patch({secondaryButtonText:value})}/><LabelInput label="2. Bağlantı" value={section.secondaryButtonHref} onChange={value=>patch({secondaryButtonHref:value})}/></div></SettingsGroup>
    {(section.items.length>0||['support','banlist','leaderboard','wiki','guide','connect','store','features','minecraft','stats','pricing','faq','team','testimonials','gallery'].includes(section.type))&&<SettingsGroup title="Liste / Kart Öğeleri"><div className="space-y-2">{section.items.map((item,index)=><div key={index} className="rounded-lg border border-white/10 bg-[#071827] p-2"><div className="flex items-center gap-1"><span className="mr-auto text-[11px] font-semibold text-cyan-300">Öğe {index+1}</span><Button size="icon" variant="ghost" className="size-7" disabled={index===0} onClick={()=>{const items=[...section.items];[items[index-1],items[index]]=[items[index],items[index-1]];patch({items})}}><ArrowUp className="size-3.5"/></Button><Button size="icon" variant="ghost" className="size-7" disabled={index===section.items.length-1} onClick={()=>{const items=[...section.items];[items[index+1],items[index]]=[items[index],items[index+1]];patch({items})}}><ArrowDown className="size-3.5"/></Button><Button size="icon" variant="ghost" className="size-7 text-red-300" onClick={()=>patch({items:section.items.filter((_,i)=>i!==index)})}><Trash2 className="size-3.5"/></Button></div><div className="mt-2 grid gap-2"><LabelInput label="Başlık / Oyuncu / Ürün" value={item.title} onChange={value=>patch({items:section.items.map((row,i)=>i===index?{...row,title:value}:row)})}/><LabelInput label="Açıklama / Detay" value={item.description} onChange={value=>patch({items:section.items.map((row,i)=>i===index?{...row,description:value}:row)})}/><div className="grid grid-cols-2 gap-2"><LabelInput label="Değer / Fiyat / Süre" value={item.value??''} onChange={value=>patch({items:section.items.map((row,i)=>i===index?{...row,value}:row)})}/><LabelInput label="Görsel URL" value={item.image??''} onChange={value=>patch({items:section.items.map((row,i)=>i===index?{...row,image:value}:row)})}/></div>{(section.type==='store'||section.type==='pricing')&&<LabelInput label={section.type==='store'?'Satın alma / ürün URL':'Plan / seçim URL'} value={item.href??''} onChange={href=>patch({items:section.items.map((row,i)=>i===index?{...row,href}:row)})}/>}</div></div>)}</div><Button size="sm" variant="outline" className="w-full border-cyan-400/25 text-cyan-100" disabled={section.items.length>=24} onClick={()=>patch({items:[...section.items,{title:'Yeni öğe',description:'Açıklamayı düzenleyin.',value:''}]})}><Plus className="size-3.5"/>Öğe Ekle</Button></SettingsGroup>}
    <SettingsGroup title="Canlı Veri"><div className="rounded-lg border border-cyan-400/15 bg-cyan-400/[.04] p-2 text-[11px] leading-5 text-slate-400"><DatabaseZap className="mr-1 inline size-3.5 text-cyan-300"/>Hazır tasarımlarda <b className="text-cyan-200">Otomatik</b> seçiliyse bölüm website ana sunucusunu devralır. Kaynak yoksa yayınlanan sitede açık veri-durumu gösterilir.</div><label className="text-xs text-slate-400">Veri modu<select className="mt-1 h-10 w-full rounded-lg border border-white/10 bg-[#071827] px-2 text-sm" value={section.liveData.mode} onChange={e=>patchLiveData({mode:e.target.value as BuilderLiveData['mode']})}><option value="static">Sabit / elle düzenlenen</option><option value="auto">Otomatik · varsa BlockCtrl canlı verisi</option><option value="source">Belirli canlı kaynak</option></select></label>{section.liveData.mode!=='static'&&<><label className="text-xs text-slate-400">Canlı kaynak<select className="mt-1 h-10 w-full rounded-lg border border-white/10 bg-[#071827] px-2 text-sm" value={section.liveData.source} onChange={e=>patchLiveData({source:e.target.value as BuilderLiveData['source']})}>{sourceTypes.length?sourceTypes.map(item=><option key={item.id} value={item.id}>{item.label}{item.native?' · Hazır':' · Plugin/API'}</option>):<><option value="server-status">Sunucu Durumu · Hazır</option><option value="players">Çevrimiçi Oyuncu · Hazır</option><option value="metrics">Performans / TPS · Hazır</option><option value="map">Dünya Haritası · Hazır</option><option value="support">Destek · Website/Sunucu</option><option value="store">Mağaza · Website/Sunucu</option><option value="wiki">Wiki · Website/Sunucu</option><option value="lost-items">Kayıp Eşya · Hazır</option><option value="leaderboard-kills">Kill Sıralaması · Agent</option><option value="leaderboard-money">Para Sıralaması · Plugin/API</option><option value="leaderboard-health">Can / Seviye · Plugin/API</option><option value="leaderboard-playtime">Oynama Süresi · Agent</option><option value="bans">Banlı Oyuncular · Agent</option><option value="custom-json">Özel JSON API</option></>}</select></label>{section.liveData.source!=='custom-json'&&<label className="text-xs text-slate-400">Sunucu<select className="mt-1 h-10 w-full rounded-lg border border-white/10 bg-[#071827] px-2 text-sm" value={section.liveData.serverId} onChange={e=>patchLiveData({serverId:e.target.value})}><option value="">Otomatik · website ana sunucusu</option>{servers.map(server=><option key={server.id} value={server.id}>{server.name}{server.id===primaryServerId?' · Ana sunucu':''} · {server.status} · {server.playerCount} oyuncu{section.liveData.source==='map'?(server.map?.configured?' · Harita hazır':' · Harita URL eksik'):''}</option>)}</select></label>}{section.liveData.source==='custom-json'&&<LabelInput label="HTTPS JSON endpoint" value={section.liveData.endpoint} onChange={endpoint=>patchLiveData({endpoint})}/>}<RangeField label={`Yenileme · ${section.liveData.refreshSeconds} sn`} min={5} max={120} value={section.liveData.refreshSeconds} onChange={refreshSeconds=>patchLiveData({refreshSeconds})}/>{section.liveData.source!=='custom-json'&&servers.length===0&&<p className="text-[11px] text-amber-300">Bu website hesabında bağlanabilir sunucu yok. Canlı bölüm yayın sırasında veri bağlantısı kuramaz.</p>}</>}</SettingsGroup>
    <SettingsGroup title="Konum & Yerleşim"><label className="text-xs text-slate-400">Yerleşim<select className="mt-1 h-10 w-full rounded-lg border border-white/10 bg-[#071827] px-2 text-sm" value={section.settings.placement} onChange={e=>patchSettings({placement:e.target.value as BuilderSection['settings']['placement']})}><option value="flow">Normal akış</option><option value="sticky-top">Üstte yapışkan</option><option value="fixed-top">Ekranın üstünde sabit</option><option value="fixed-bottom">Ekranın altında sabit</option></select></label><label className="text-xs text-slate-400">Genişlik<select className="mt-1 h-10 w-full rounded-lg border border-white/10 bg-[#071827] px-2 text-sm" value={section.settings.width} onChange={e=>patchSettings({width:e.target.value as BuilderSection['settings']['width']})}><option value="boxed">Kutu içinde</option><option value="wide">Geniş</option><option value="full">Tam genişlik</option></select></label><div className="grid grid-cols-3 gap-2"><AlignButton active={section.settings.align==='left'} onClick={()=>patchSettings({align:'left'})}><AlignLeft className="size-4"/></AlignButton><AlignButton active={section.settings.align==='center'} onClick={()=>patchSettings({align:'center'})}><AlignCenter className="size-4"/></AlignButton><AlignButton active={section.settings.align==='right'} onClick={()=>patchSettings({align:'right'})}><AlignRight className="size-4"/></AlignButton></div><RangeField label={`Dikey boşluk · ${section.settings.paddingY}px`} min={0} max={140} value={section.settings.paddingY} onChange={value=>patchSettings({paddingY:value})}/><RangeField label={`Minimum yükseklik · ${section.settings.minHeight}px`} min={60} max={900} value={section.settings.minHeight} onChange={value=>patchSettings({minHeight:value})}/><label className="flex items-center justify-between rounded-lg border border-white/10 p-2 text-xs"><span>Bölümü göster</span><input type="checkbox" checked={section.settings.visible} onChange={e=>patchSettings({visible:e.target.checked})} className="accent-cyan-400"/></label></SettingsGroup>
    <SettingsGroup title="Arka Plan"><label className="text-xs text-slate-400">Tür<select className="mt-1 h-10 w-full rounded-lg border border-white/10 bg-[#071827] px-2 text-sm" value={section.background.type} onChange={e=>patchBackground({type:e.target.value as BuilderBackground['type']})}><option value="color">Renk</option><option value="gradient">Gradyan</option><option value="image">Görsel</option><option value="video">Video</option></select></label>{section.background.type==='color'&&<ColorField label="Arka plan rengi" value={section.background.color} onChange={value=>patchBackground({color:value})}/>} {section.background.type==='gradient'&&<LabelInput label="CSS gradyan" value={section.background.gradient} onChange={value=>patchBackground({gradient:value})}/>} {(section.background.type==='image'||section.background.type==='video')&&<><LabelInput label="Medya URL" value={section.background.mediaUrl} onChange={value=>patchBackground({mediaUrl:value})}/><label className="flex cursor-pointer items-center justify-center gap-2 rounded-lg border border-dashed border-cyan-400/25 bg-cyan-400/[.04] px-3 py-3 text-xs text-cyan-200 hover:bg-cyan-400/[.08]"><Upload className="size-4"/>{uploading?'Yükleniyor...':'Bilgisayardan görsel / video yükle'}<input type="file" accept="image/*,video/mp4,video/webm,video/quicktime" className="hidden" disabled={uploading} onChange={e=>{const file=e.target.files?.[0];if(file)void uploadBackground(file);e.currentTarget.value='' }}/></label>{section.background.mediaUrl&&<Button size="sm" variant="outline" className="w-full border-red-500/25 text-red-300" onClick={()=>patchBackground({mediaUrl:'',type:'color'})}><Trash2 className="size-3.5"/>Arka plan medyasını kaldır</Button>}</>}<div className="grid grid-cols-2 gap-2"><ColorField label="Şeffaf katman" value={section.background.overlayColor} onChange={value=>patchBackground({overlayColor:value})}/><RangeField label={`Opaklık · %${section.background.overlayOpacity}`} min={0} max={95} value={section.background.overlayOpacity} onChange={value=>patchBackground({overlayOpacity:value})}/></div><label className="text-xs text-slate-400">Görsel konumu<select className="mt-1 h-10 w-full rounded-lg border border-white/10 bg-[#071827] px-2 text-sm" value={section.background.position} onChange={e=>patchBackground({position:e.target.value as BuilderBackground['position']})}><option value="center">Orta</option><option value="top">Üst</option><option value="bottom">Alt</option><option value="left">Sol</option><option value="right">Sağ</option></select></label></SettingsGroup>
  </div>
}
function PageSettings({page,patch}:{page:BuilderPage;patch:(p:Partial<BuilderPage>)=>void}){return <div className="space-y-4"><SettingsGroup title="Sayfa Bilgileri"><LabelInput label="Sayfa adı" value={page.name} onChange={value=>patch({name:value})}/><LabelInput label="URL" value={page.slug} onChange={value=>patch({slug:slugify(value)})}/><label className="text-xs text-slate-400">Sayfa türü<select className="mt-1 h-10 w-full rounded-lg border border-white/10 bg-[#071827] px-2 text-sm" value={page.pageType} onChange={e=>patch({pageType:e.target.value as BuilderPage['pageType'],requiresAuth:e.target.value==='member-dashboard'?true:page.requiresAuth,accessMode:e.target.value==='member-dashboard'?'authenticated':page.accessMode})}><option value="standard">Standart</option><option value="login">Giriş</option><option value="register">Kayıt</option><option value="member-dashboard">Üye Paneli</option></select></label><label className="flex items-center justify-between rounded-lg border border-white/10 p-2 text-xs"><span>Menüde göster</span><input type="checkbox" checked={page.showInNav} onChange={e=>patch({showInNav:e.target.checked})} className="accent-cyan-400"/></label></SettingsGroup><SettingsGroup title="Sayfa Erişimi"><label className="text-xs text-slate-400">Kim görebilir?<select className="mt-1 h-10 w-full rounded-lg border border-white/10 bg-[#071827] px-2 text-sm" value={page.accessMode} onChange={e=>{const accessMode=e.target.value as BuilderPage['accessMode'];patch({accessMode,requiresAuth:accessMode!=='public'})}}><option value="public">Herkes</option><option value="authenticated">Giriş yapan tüm üyeler</option><option value="assigned">Sadece erişim verilen üyeler</option><option value="role">Belirli roller</option></select></label>{page.accessMode==='role'&&<div className="space-y-2"><p className="text-xs text-slate-500">Bu sayfaya girebilecek roller:</p>{['member','vip','staff'].map(role=><label key={role} className="flex items-center justify-between rounded-lg border border-white/10 p-2 text-xs"><span>{role}</span><input type="checkbox" checked={page.allowedRoles.includes(role)} onChange={e=>patch({allowedRoles:e.target.checked?[...new Set([...page.allowedRoles,role])]:page.allowedRoles.filter(item=>item!==role)})} className="accent-violet-400"/></label>)}</div>}{page.accessMode==='assigned'&&<div className="rounded-lg border border-violet-400/15 bg-violet-400/[.04] p-2 text-[11px] leading-5 text-slate-400">Bu sayfa yalnız Website Yönetimi → Üye Sistemi ekranında erişim verilen kullanıcılara gösterilir.</div>}</SettingsGroup><SettingsGroup title="SEO"><LabelInput label="SEO başlık" value={page.seoTitle} onChange={value=>patch({seoTitle:value})}/><label className="text-xs text-slate-400">SEO açıklama<textarea rows={4} className="mt-1 w-full rounded-lg border border-white/10 bg-[#071827] p-2.5 text-sm text-white" value={page.seoDescription} onChange={e=>patch({seoDescription:e.target.value})}/></label></SettingsGroup></div>}
function SettingsGroup({title,children}:{title:string;children:React.ReactNode}){return <div className="space-y-3 rounded-xl border border-white/10 bg-white/[.02] p-3"><p className="text-xs font-semibold uppercase tracking-wider text-slate-500">{title}</p>{children}</div>}
function LabelInput({label,value,onChange}:{label:string;value:string;onChange:(v:string)=>void}){return <label className="block text-xs text-slate-400">{label}<Input className="mt-1 border-white/10 bg-[#071827] text-white" value={value} onChange={e=>onChange(e.target.value)}/></label>}
function ColorField({label,value,onChange}:{label:string;value:string;onChange:(v:string)=>void}){return <label className="block text-xs text-slate-400">{label}<div className="mt-1 flex h-10 items-center gap-2 rounded-lg border border-white/10 bg-[#071827] px-2"><input type="color" value={/^#[0-9a-f]{6}$/i.test(value)?value:'#000000'} onChange={e=>onChange(e.target.value)} className="h-7 w-8 cursor-pointer border-0 bg-transparent"/><input value={value} onChange={e=>onChange(e.target.value)} className="min-w-0 flex-1 bg-transparent text-xs text-white outline-none"/></div></label>}
function RangeField({label,min,max,value,onChange}:{label:string;min:number;max:number;value:number;onChange:(v:number)=>void}){return <label className="block text-xs text-slate-400">{label}<input type="range" min={min} max={max} value={value} onChange={e=>onChange(Number(e.target.value))} className="mt-2 w-full accent-cyan-400"/></label>}
function AlignButton({active,onClick,children}:{active:boolean;onClick:()=>void;children:React.ReactNode}){return <button type="button" onClick={onClick} className={`grid h-10 place-items-center rounded-lg border ${active?'border-cyan-400/50 bg-cyan-400/10 text-cyan-200':'border-white/10 bg-[#071827] text-slate-400'}`}>{children}</button>}

function SectionPreview({section,theme,pages,liveServer}:{section:BuilderSection;theme:WebsiteBuilderData['theme'];pages:BuilderPage[];liveServer?:LiveServerOption}){
  const previewItems=liveServer&&section.liveData.mode!=='static'&&['server-status','players','metrics'].includes(section.liveData.source)?[{title:'Çevrimiçi Oyuncu',description:liveServer.name,value:String(liveServer.metrics?.players??liveServer.playerCount)},{title:'Sunucu Durumu',description:`${liveServer.loader} ${liveServer.mcVersion}`,value:liveServer.status==='running'?'Çalışıyor':'Kapalı'},{title:'TPS',description:'Canlı telemetri',value:liveServer.metrics?.tps==null?'—':String(liveServer.metrics.tps)},{title:'Uptime',description:'Canlı telemetri',value:liveServer.metrics?.uptimeSeconds?`${Math.floor(liveServer.metrics.uptimeSeconds/3600)} sa`:'—'}]:section.items
  const placement=section.settings.placement==='sticky-top'?'sticky top-0 z-20':section.settings.placement==='fixed-top'?'sticky top-0 z-20':section.settings.placement==='fixed-bottom'?'sticky bottom-0 z-20':''
  const bgStyle:React.CSSProperties={backgroundColor:section.background.color,backgroundImage:section.background.type==='gradient'?section.background.gradient:section.background.type==='image'&&section.background.mediaUrl?`url(${section.background.mediaUrl})`:undefined,backgroundPosition:section.background.position,backgroundSize:'cover',minHeight:section.settings.minHeight,paddingTop:section.settings.paddingY,paddingBottom:section.settings.paddingY}
  const inner=section.settings.width==='boxed'?'max-w-5xl':section.settings.width==='wide'?'max-w-7xl':'max-w-none'
  const align=section.settings.align==='center'?'text-center items-center':section.settings.align==='right'?'text-right items-end':'text-left items-start'
  return <section className={`relative overflow-hidden ${placement}`} style={bgStyle}>{section.background.type==='video'&&section.background.mediaUrl&&<video src={section.background.mediaUrl} autoPlay muted loop playsInline className="absolute inset-0 size-full object-cover"/>}{(section.background.type==='image'||section.background.type==='video')&&<div className="absolute inset-0" style={{background:section.background.overlayColor,opacity:section.background.overlayOpacity/100}}/>}<div className={`relative z-10 mx-auto flex w-full flex-col px-6 md:px-10 ${inner} ${align}`}>
    {section.liveData.mode!=='static'&&<div className="mb-3 inline-flex self-start items-center rounded-full border border-emerald-400/20 bg-emerald-400/10 px-2.5 py-1 text-[10px] font-semibold text-emerald-300"><DatabaseZap className="mr-1 size-3"/>Canlı veri · {liveServer?.name||'Kaynak bekleniyor'}</div>}
    {section.type==='login'?<><Heading section={section}/><div className="mx-auto mt-8 w-full max-w-md space-y-3 rounded-2xl border border-white/10 bg-black/25 p-6 text-left"><label className="text-xs text-slate-400">E-posta<div className="mt-1 h-11 rounded-lg border border-white/10 bg-white/[.04]"/></label><label className="text-xs text-slate-400">Şifre<div className="mt-1 h-11 rounded-lg border border-white/10 bg-white/[.04]"/></label><div className="h-11 rounded-lg text-center text-sm font-semibold leading-[44px] text-white" style={{background:theme.primary}}>Giriş Yap</div><p className="text-center text-xs text-slate-500">Hesabın yok mu? Kayıt ol</p></div></>:section.type==='register'?<><Heading section={section}/><div className="mx-auto mt-8 grid w-full max-w-lg gap-3 rounded-2xl border border-white/10 bg-black/25 p-6 text-left sm:grid-cols-2">{['Ad Soyad','Minecraft Kullanıcı Adı','E-posta','Şifre'].map(label=><label key={label} className="text-xs text-slate-400">{label}<div className="mt-1 h-11 rounded-lg border border-white/10 bg-white/[.04]"/></label>)}<div className="h-11 rounded-lg text-center text-sm font-semibold leading-[44px] text-white sm:col-span-2" style={{background:theme.primary}}>Kayıt Ol</div></div></>:section.type==='member-dashboard'?<><Heading section={section}/><div className="mt-8 grid w-full gap-3 md:grid-cols-3"><div className="rounded-xl border border-white/10 bg-black/20 p-5 text-left md:col-span-1"><div className="size-14 rounded-full bg-white/10"/><p className="mt-3 font-semibold">Üye Profili</p><p className="mt-1 text-xs text-slate-400">Ad, e-posta ve Minecraft hesabı burada görünür.</p></div><div className="grid gap-3 sm:grid-cols-2 md:col-span-2">{previewItems.slice(0,4).map((item,index)=><div key={index} className="rounded-xl border border-white/10 bg-black/20 p-5 text-left"><p className="text-xs text-slate-500">{item.title}</p><b className="mt-2 block text-xl" style={{color:theme.primary}}>{item.value}</b><p className="mt-1 text-xs text-slate-400">{item.description}</p></div>)}</div></div></>:section.type==='navbar'?<div className="flex w-full items-center gap-5"><b className="text-lg" style={{color:theme.text}}>{section.title||'LOGO'}</b><nav className="ml-auto hidden gap-5 text-xs md:flex">{pages.filter(p=>p.showInNav).slice(0,6).map(p=><span key={p.id} className="text-slate-300">{p.name}</span>)}</nav>{section.buttonText&&<span className="rounded-lg px-4 py-2 text-xs font-semibold text-white" style={{background:theme.primary}}>{section.buttonText}</span>}</div>:
    section.type==='stats'?<><Heading section={section}/><div className="mt-8 grid w-full grid-cols-2 gap-3 md:grid-cols-4">{previewItems.map((item,index)=><div key={index} className="rounded-xl border border-white/10 bg-black/20 p-4"><b className="text-2xl" style={{color:theme.primary}}>{item.value}</b><p className="mt-1 text-xs font-medium">{item.title}</p><p className="text-[11px] text-slate-400">{item.description}</p></div>)}</div></>:
    section.type==='support'?<><Heading section={section}/><div className="mt-8 grid w-full gap-3 md:grid-cols-2"><div className="space-y-3 rounded-xl border border-white/10 bg-black/20 p-5 text-left"><label className="text-xs text-slate-400">Adınız<div className="mt-1 h-10 rounded-lg border border-white/10 bg-white/[.03]"/></label><label className="text-xs text-slate-400">E-posta<div className="mt-1 h-10 rounded-lg border border-white/10 bg-white/[.03]"/></label><label className="text-xs text-slate-400">Destek konusu<div className="mt-1 h-10 rounded-lg border border-white/10 bg-white/[.03]"/></label><label className="text-xs text-slate-400">Mesaj<div className="mt-1 h-24 rounded-lg border border-white/10 bg-white/[.03]"/></label><div className="h-10 rounded-lg text-center text-xs font-semibold leading-10 text-white" style={{background:theme.primary}}>Destek Talebi Gönder</div></div><div className="space-y-2 rounded-xl border border-white/10 bg-black/20 p-5 text-left"><p className="text-sm font-semibold">Destek konuları</p>{previewItems.slice(0,6).map((item,index)=><div key={index} className="rounded-lg border border-white/10 bg-white/[.025] p-3"><p className="text-xs font-medium text-white">{item.title}</p><p className="mt-1 text-[11px] leading-5 text-slate-400">{item.description}</p></div>)}</div></div></>:
    section.type==='map'?<><Heading section={section}/><div className="mt-8 grid w-full gap-4 lg:grid-cols-[minmax(0,1.65fr)_minmax(260px,.65fr)]"><div className="relative min-h-[360px] overflow-hidden rounded-2xl border border-cyan-400/20 bg-[#06111c] text-left shadow-[inset_0_0_70px_rgba(14,165,233,.06)]"><div className="absolute inset-0 opacity-30" style={{backgroundImage:`linear-gradient(rgba(56,189,248,.14) 1px,transparent 1px),linear-gradient(90deg,rgba(56,189,248,.14) 1px,transparent 1px)`,backgroundSize:'34px 34px'}}/><div className="absolute inset-0 bg-[radial-gradient(circle_at_35%_42%,rgba(34,197,94,.22),transparent_12%),radial-gradient(circle_at_62%_62%,rgba(14,165,233,.2),transparent_16%),radial-gradient(circle_at_78%_25%,rgba(168,85,247,.18),transparent_10%)]"/><div className="absolute left-[35%] top-[42%] -translate-x-1/2 -translate-y-1/2"><div className="grid size-11 place-items-center rounded-full border border-emerald-300/40 bg-emerald-400/15 text-emerald-200 shadow-[0_0_30px_rgba(52,211,153,.18)]"><MapPinned className="size-5"/></div><span className="mt-2 block rounded-md bg-black/55 px-2 py-1 text-[10px] text-white">Spawn</span></div><div className="absolute bottom-4 left-4 rounded-lg border border-white/10 bg-black/45 px-3 py-2 text-[11px] text-slate-300">BlueMap / Dynmap önizlemesi</div></div><div className="space-y-2">{previewItems.slice(1,5).map((item,index)=><div key={index} className="rounded-xl border border-white/10 bg-black/20 p-4 text-left"><div className="flex items-center gap-2"><MapPinned className="size-4" style={{color:theme.primary}}/><p className="font-semibold">{item.title}</p></div><p className="mt-1 text-xs leading-5 text-slate-400">{item.description}</p>{item.value&&<p className="mt-2 font-mono text-[11px]" style={{color:theme.primary}}>{item.value}</p>}</div>)}</div></div></>:
    section.type==='features'||section.type==='minecraft'||section.type==='wiki'||section.type==='guide'||section.type==='connect'?<><Heading section={section}/><div className="mt-8 grid w-full gap-3 md:grid-cols-2 xl:grid-cols-4">{previewItems.map((item,index)=><div key={index} className="rounded-xl border border-white/10 bg-black/20 p-5"><div className="mb-3 grid size-10 place-items-center rounded-lg" style={{background:`${theme.primary}22`,color:theme.primary}}><LayoutGrid className="size-5"/></div><div className="flex items-start justify-between gap-3"><p className="font-semibold">{item.title}</p>{item.value&&<span className="rounded-full border border-cyan-400/25 bg-cyan-400/10 px-2 py-1 text-[10px] text-cyan-200">{item.value}</span>}</div><p className="mt-1 text-xs leading-5 text-slate-400">{item.description}</p></div>)}</div></>:
    section.type==='banlist'?<><Heading section={section}/><div className="mt-8 grid w-full gap-2">{previewItems.map((item,index)=><div key={index} className="grid grid-cols-[44px_1fr_auto] items-center gap-3 rounded-xl border border-red-400/15 bg-red-500/[.04] p-4 text-left"><div className="grid size-10 place-items-center rounded-lg bg-red-500/10 text-sm font-black text-red-300">{index+1}</div><div><p className="font-semibold">{item.title}</p><p className="mt-1 text-xs text-slate-400">{item.description}</p></div><span className="rounded-full border border-red-400/25 bg-red-500/10 px-3 py-1 text-xs text-red-200">{item.value}</span></div>)}</div></>:
    section.type==='leaderboard'?<><Heading section={section}/><div className="mt-8 grid w-full gap-2">{previewItems.map((item,index)=><div key={index} className={`grid grid-cols-[48px_1fr_auto] items-center gap-3 rounded-xl border p-4 text-left ${index===0?'border-amber-400/30 bg-amber-400/[.06]':'border-white/10 bg-black/20'}`}><div className="grid size-10 place-items-center rounded-lg bg-white/[.05] font-black" style={{color:index===0?'#fbbf24':theme.primary}}>#{index+1}</div><div><p className="font-semibold">{item.title}</p><p className="mt-1 text-xs text-slate-400">{item.description}</p></div><b className="text-sm" style={{color:theme.primary}}>{item.value}</b></div>)}</div></>:
    section.type==='store'?<><Heading section={section}/><div className="mt-8 grid w-full gap-3 md:grid-cols-2 xl:grid-cols-4">{previewItems.map((item,index)=><div key={index} className="rounded-xl border border-white/10 bg-black/20 p-5 text-left"><div className="mb-4 aspect-[16/8] rounded-lg bg-[linear-gradient(135deg,#12314a,#21103b)]"/><p className="font-semibold">{item.title}</p><b className="mt-2 block text-2xl" style={{color:theme.primary}}>{item.value}</b><p className="mt-2 text-xs leading-5 text-slate-400">{item.description}</p><div className="mt-4 rounded-lg px-3 py-2 text-center text-xs font-semibold text-white" style={{background:theme.primary}}>Satın Al</div></div>)}</div></>:
    section.type==='pricing'?<><Heading section={section}/><div className="mt-8 grid w-full gap-3 md:grid-cols-3">{previewItems.map((item,index)=><div key={index} className={`rounded-xl border p-5 ${index===1?'border-cyan-400/40 bg-cyan-400/[.06]':'border-white/10 bg-black/20'}`}><p className="font-semibold">{item.title}</p><b className="mt-3 block text-3xl">{item.value}</b><p className="mt-2 text-xs text-slate-400">{item.description}</p><div className="mt-4 rounded-lg px-3 py-2 text-center text-xs font-semibold text-white" style={{background:theme.primary}}>Seç</div></div>)}</div></>:
    section.type==='gallery'?<><Heading section={section}/><div className="mt-8 grid w-full grid-cols-2 gap-3 md:grid-cols-4">{previewItems.map((item,index)=><div key={index} className="aspect-square overflow-hidden rounded-xl border border-white/10 bg-[linear-gradient(135deg,#12314a,#160f2b)]">{item.image?<img src={item.image} alt="" className="size-full object-cover"/>:<div className="grid size-full place-items-center text-slate-500"><ImageIcon className="size-7"/></div>}</div>)}</div></>:
    section.type==='faq'?<><Heading section={section}/><div className="mt-8 grid w-full gap-2">{previewItems.map((item,index)=><div key={index} className="rounded-xl border border-white/10 bg-black/20 p-4 text-left"><p className="font-medium">{item.title}</p><p className="mt-1 text-xs text-slate-400">{item.description}</p></div>)}</div></>:
    section.type==='team'||section.type==='testimonials'?<><Heading section={section}/><div className="mt-8 grid w-full gap-3 md:grid-cols-3 xl:grid-cols-4">{previewItems.map((item,index)=><div key={index} className="rounded-xl border border-white/10 bg-black/20 p-5"><div className="mb-3 size-11 rounded-full bg-white/10"/><p className="font-semibold">{item.title}</p><p className="mt-1 text-xs leading-5 text-slate-400">{item.description}</p></div>)}</div></>:
    section.type==='contact'?<><Heading section={section}/><div className="mt-8 grid w-full gap-3 md:grid-cols-2"><div className="space-y-3 rounded-xl border border-white/10 bg-black/20 p-5"><div className="h-10 rounded-lg border border-white/10 bg-white/[.03]"/><div className="h-10 rounded-lg border border-white/10 bg-white/[.03]"/><div className="h-24 rounded-lg border border-white/10 bg-white/[.03]"/><div className="h-10 rounded-lg" style={{background:theme.primary}}/></div><div className="rounded-xl border border-white/10 bg-black/20 p-5 text-sm text-slate-400">İletişim bilgileri, adres, Discord ve sosyal medya bağlantıları burada gösterilir.</div></div></>:
    section.type==='footer'?<div className="grid w-full gap-5 md:grid-cols-4"><div><b className="text-lg">{section.title}</b><p className="mt-2 text-xs leading-5 text-slate-400">{section.body}</p></div>{['Ürün','Şirket','Yasal'].map(group=><div key={group}><p className="text-xs font-semibold">{group}</p><div className="mt-2 space-y-1 text-xs text-slate-500"><p>Bağlantı</p><p>Bağlantı</p><p>Bağlantı</p></div></div>)}</div>:
    <><Heading section={section}/>{section.type==='content'&&<div className="mt-8 grid w-full gap-6 md:grid-cols-2"><div className="min-h-44 rounded-xl border border-white/10 bg-[linear-gradient(135deg,#11304b,#160f2b)]"/><div className="flex flex-col justify-center text-sm leading-7 text-slate-300">{section.body}</div></div>}</>}
  </div></section>
}
function Heading({section}:{section:BuilderSection}){return <div className={`flex max-w-4xl flex-col ${section.settings.align==='center'?'items-center':section.settings.align==='right'?'items-end':'items-start'}`}><p className="text-xs font-semibold uppercase tracking-[.18em] text-cyan-300">{section.subtitle}</p><h2 className={`${section.type==='hero'?'mt-4 text-4xl md:text-6xl':'mt-3 text-2xl md:text-3xl'} font-black tracking-[-.04em]`}>{section.title}</h2><p className="mt-4 max-w-2xl text-sm leading-7 text-slate-300">{section.body}</p>{section.type==='hero'||section.type==='cta'?<div className="mt-6 flex flex-wrap gap-3"><span className="rounded-lg bg-cyan-500 px-5 py-3 text-sm font-semibold text-white">{section.buttonText}</span>{section.secondaryButtonText&&<span className="rounded-lg border border-white/15 bg-black/10 px-5 py-3 text-sm">{section.secondaryButtonText}</span>}</div>:null}</div>}
